# -*- coding: utf-8 -*-
# 2026 케이스북 퀴즈 국문 (10·11장)
C = []
def c(n, q, a, e, arts, ox=None, ch=None, cEn=None, scene=None):
    d = {'n': n, 'q': q, 'a': a, 'e': e, 'arts': arts}
    if ox is not None: d['ox'] = ox
    if ch: d['c'] = ch
    if cEn: d['cEn'] = cEn
    if scene: d['scene'] = scene
    C.append(d)

c('10.84.1', 'A1이 트라이를 성공해 레퍼리가 신호한 직후 B2가 A1을 쳤지만 접촉은 아주 가벼웠다. 트라이가 이미 인정되었으니 레퍼리는 이 접촉을 무시해야 하는가?', 0,
  '케이스북 10.84.1의 답: 무시한다. 득점 뒤의 가벼운 접촉은 경기를 멈출 만한 파울이 아니다.', [84], ox=0)
c('10.84.2', 'B1이 트라이 라인 근처에서 A1을 쫓다가 충돌했다. 축보다 뒤에서 충돌했고 수비 각도에 큰 변화는 없었지만 A1이 불리해졌다. B1은 휠체어나 볼에 적법한 수비를 하려고 합리적으로 노력했다. 레퍼리는 어떻게 판정하는가?', 0,
  '케이스북 10.84.2 B)의 답: 불법 접촉이다. 축 뒤에서의 충돌로 상대가 불리해지면 불법 접촉이며, 속도와 강도에 따라 수비자 파울(스피닝·푸싱 파울 등)을 주거나 위험하지 않으면 그냥 넘어갈 수도 있다. 같은 케이스 A)처럼 축 위나 앞에서, 적법한 수비를 할 수 있는 각도에서 한 충돌은 적법한 접촉이다.', [84, 85],
  ch=['불법 접촉 — 수비자 파울', '적법한 접촉 — 파울 없음', '양쪽 모두 파울'], cEn=['Illegal contact - defensive foul', 'Legal contact - no foul', 'Fouls on both players'])
c('11.88.1', 'A1이 수비 없이 트라이 라인으로 가다가 시간을 끌려고 일부러 멈췄다. B1이 A1을 무시하고 포스트 사이로 코트를 벗어났다. 레퍼리는 페널티 트라이를 선언해야 하는가?', 1,
  '케이스북 11.88.1의 답: A1이 멈췄으므로 즉시 득점 의도가 없었다고 보아 페널티 트라이는 줄 수 없다. B1에게 코트 이탈 파울을 주고 A팀에 사이드라인 스로인을 준다.', [88, 93], ox=1)
c('11.88.2', 'A1이 트라이 라인으로 달리고 B1이 옆에서 길을 막으려 했다. 라인에 가까워지자 A1이 일부러 속도를 줄여 B1이 먼저 트라이 라인을 넘게 했다. 레퍼리가 A1에게 페널티 트라이를 준 것은 옳은가?', 1,
  '케이스북 11.88.2의 답: 옳지 않다. 일부러 속도를 줄인 것은 득점보다 B1을 코트 이탈 파울로 끌어들이려는 의도다. B1에게 코트 이탈 파울과 페널티를 준다.', [88, 93], ox=1)
c('11.88.3', 'A1이 트라이 라인으로 달리고 B1이 옆에서 길을 막으며 접촉했고, 그 과정에서 B1이 A1보다 먼저 트라이 라인을 넘었다. 레퍼리가 A1에게 페널티 트라이를 준 것은 옳은가?', 0,
  '케이스북 11.88.3의 답: 옳다. 득점할 수 있는 위치에 있던 A1이 득점을 막혔으므로 페널티 트라이를 주어야 한다.', [88, 93], ox=0)
c('11.89.1', 'A1이 키로 들어가다 트라이 라인으로 가는 길이 막혀 볼을 패스하고 정지해 있던 수비수에게 부딪혔다. 레퍼리가 A1에게 차징 파울을 준 것은 옳은가?', 1,
  '케이스북 11.89.1의 답: 옳지 않다. 그 수비수는 키 안에서 트라이 라인으로 가는 길 전체를 막고 있었으므로 경기에 적극적으로 참여한 선수다. 따라서 차징 파울을 적용할 수 없다.', [89, 84], ox=1)
c('11.89.2', 'A1이 트라이 라인으로 가는 좁은 틈을 막아서는 두 수비수보다 빠르게 달리다 그대로 밀고 들어가, 수비수의 휠체어가 옆으로 돌아갈 만큼 강하게 충돌하며 득점했다. 레퍼리가 트라이를 취소하고 A1에게 차징 파울을 준 것은 옳은가?', 1,
  '케이스북 11.89.2의 답: 옳지 않다. 득점을 노리는 볼 소유자의 힘은 언제나 허용된다. 위험하거나 비신사적인 플레이로 테크니컬·디스퀄리파잉 파울이 되는 경우만 예외다.', [89], ox=1)
c('11.89.3', 'B2가 달려와 A3의 범퍼를 쳐서 A3의 휠체어가 180도 돌아갔다. 레퍼리가 B2에게 차징 파울을 준 것은 옳은가?', 1,
  '케이스북 11.89.3의 답: 옳지 않다. 상대의 방향을 크게 바꾸게 했다고 해서 곧바로 차징 파울은 아니다. 맞은 선수가 경기에 적극적으로 참여하지 않았고 부상 위험이 있었다고 판단될 때라야 한다.', [89, 84], ox=1)
c('11.90.1', '트라이 직후, 레퍼리의 호각이 울리기 전에 A2가 몰려 있는 선수들 사이에서 빠져나오려 했다. B2가 가볍게 접촉해 A2의 진행 방향을 바꿔 A2를 불리하게 만들었다. 레퍼리는 가벼운 접촉이니 무시해야 하는가?', 1,
  '케이스북 11.90.1의 답: 무시할 수 없다. A2가 호각 전 접촉으로 불리해졌으므로 B2에게 파울(호각 전 접촉)을 주어야 한다.', [90], ox=1)
c('11.90.2', '트라이 직후 호각 전에 A2와 B3가 몰린 곳에서 빠져나오려다 서로 가볍게 부딪혔다. 레퍼리가 이 접촉을 무시하고 경기를 계속하게 했다. 옳은가?', 0,
  '케이스북 11.90.2의 답: 옳다. 접촉이 경미했고 어느 쪽도 불리해지지 않았다.', [90], ox=0)
c('11.90.3', '호각 전에 A2가 B3에게 붙어 휠체어를 고정해 B3가 자유롭게 움직이지 못하게 했다. 레퍼리는 우연한 접촉으로 보고 경기를 계속하게 했다. 옳은가?', 1,
  '케이스북 11.90.3의 답: 옳지 않다. 부딪히는 소리가 나지 않았더라도 그 접촉은 호각 전에 B3를 불리하게 만든 것이다.', [90], ox=1)
c('11.91.1', 'B3가 키 위쪽에서 수비하던 중 A2의 충돌을 받아 키 안으로 굴러 들어가 네 번째 수비수가 되었다. 레퍼리가 B3에게 포 인 더 키 파울을 준 것은 옳은가?', 0,
  '케이스북 11.91.1의 답: 옳다. A2의 충돌이 적법했으므로 키 안으로 밀려 들어간 B3에게 포 인 더 키 파울을 준다.', [91], ox=0, scene='11.91.1')
c('11.91.2', '키 위쪽에 있던 B2가 A1의 득점을 막으려고 포스트 근처로 이동하면서 키를 잠깐 통과해 순간적으로 네 번째 수비수가 되었다. 레퍼리가 B2에게 파울을 주는 것이 옳은가?', 0,
  '케이스북 11.91.2 a)의 답: 옳다. B2가 이점을 얻었으므로 포 인 더 키 파울을 준다. 같은 케이스 b)처럼 A팀 선수들이 센터라인을 넘거나 백코트에 있어 B팀이 이점을 얻지 못한 경우에는 파울이 아니다.', [91], ox=0)
c('11.91.3', 'B2가 키 위쪽에서 네 번째 수비수로 있던 중 방향을 돌리며 앞 캐스터를 들어 키 위를 바닥에 닿지 않고 지나갔다. 레퍼리는 키 안 공간을 잠깐 차지했다며 네 번째 수비수 파울을 주었다. 옳은가?', 1,
  '케이스북 11.91.3의 답: 옳지 않다. 선수의 위치는 바닥과 닿은 지점으로 정한다.', [91, 63], ox=1)
c('11.92.1', 'A2가 달려와 B2의 범퍼를 쳐서 B2가 무릎 위로 쓰러졌고, 그 때문에 A2가 더 밀고 나아갈 수 없게 되었다. 레퍼리가 B2에게 홀딩 파울을 준 것은 옳은가?', 0,
  '케이스북 11.92.1의 답: 옳다. 충돌은 적법했지만 B2가 A2의 진행을 막아 불리하게 만들었다.', [92], ox=0)
c('11.92.2', 'A2와 B2가 서로 부딪혔고, 그 충격으로 균형을 잃은 B2가 A2의 무릎을 가볍게 스쳤다. 레퍼리가 B2에게 홀딩 파울을 준 것은 옳은가?', 1,
  '케이스북 11.92.2의 답: 옳지 않다. 짧게 스쳤을 뿐 불리해진 것이 없으므로 경기를 계속하게 해야 한다.', [92], ox=1)
c('11.92.3', 'A1이 볼을 랩에 얹고 가던 중 B1이 A1의 수직 공간으로 손을 넣어 A1과 접촉하지 않은 채 볼에 닿았다. 헬드볼 위험을 느낀 A1이 팔꿈치로 B1을 몸에 붙잡았다. 레퍼리가 B1에게 일리걸 유스 오브 더 핸즈 파울을 준 것은 옳은가?', 1,
  '케이스북 11.92.3의 답: 옳지 않다. B1은 접촉을 만들지 않았다. A1이 공격자 홀딩을 범한 것이다.', [92, 95], ox=1)
c('11.93.1', 'A2가 사이드라인을 따라 B1을 앞지르려는데 B1이 A2를 코트 밖으로 밀어냈다. A2가 그대로 코트 밖으로 달려 결국 B1을 앞질렀다. 밀려서 나갔으니 경기를 계속하게 해야 하는가?', 1,
  '케이스북 11.93.1의 답: 안 된다. 코트 밖에서 이득(어드밴티지)을 본 A2에게 코트 이탈 파울을 준다. 선수는 코트를 벗어난 지점에서 가장 가까운 곳으로 다시 들어와야 한다.', [93, 87], ox=1)
c('11.93.2', 'A팀이 프론트코트 엔드라인 근처에서 스로인을 얻었다. 접촉을 허용하는 호각 전에 A2가 스로인 지점과 가장 가까운 키 자리를 트라이 라인을 보고 잡았고, B1이 A2 옆(A2와 인바운더 사이)에, B3가 A2 바로 뒤에 자리를 잡았다. 호각이 울려 볼이 라이브 상태가 된 뒤 B3가 A2를 한 번 쳐서 A2가 포스트 사이로 굴러 나갔다. 어떻게 판정하는가?', 0,
  '케이스북 11.93.2 a)의 답: 한 번 친 것이면 A2에게 코트 이탈 파울을 준다. 같은 케이스 b)처럼 B3가 계속 밀어서 아웃시켰다면 B3에게 푸싱 파울을 준다.', [93, 94],
  ch=['A2에게 코트 이탈 파울', 'B3에게 푸싱 파울', '파울 없음'], cEn=['Leaving the court foul on A2', 'Pushing foul on B3', 'No foul'])
c('11.93.3', 'A1이 트라이 라인 근처에서 B1의 압박을 받으며 A2에게 패스했고, 패스 후 뒤로 물러나다 키 밖의 포스트에 닿았다. 레퍼리가 코트 이탈 파울을 선언했다. 옳은가?', 1,
  '케이스북 11.93.3의 답: 옳지 않다. A1은 볼을 갖고 있지 않았고 포스트 사이에서 코트를 벗어난 것도 아니므로 콜하지 않는다.', [93], ox=1)
c('11.93.4', 'A2가 사이드라인 근처에서 B3와 B4에게 막혀 벗어나려다 코트를 벗어났다. B3와 B4가 A2에게 다가가 코트로 다시 들어오지 못하게 막았다. 레퍼리가 그냥 경기를 계속하게 한 것은 옳은가?', 1,
  '케이스북 11.93.4의 답: 옳지 않다. B3와 B4에게 선수를 다시 들여보내라고 지시해야 한다. 다만 A2는 재입장으로 이점을 얻을 수 없다.', [93], ox=1)
c('11.93.7', 'A1이 포스트 근처에서 득점하려는데 B1이 먼저 라인 쪽으로 내려와 포스트와 범퍼 사이를 몇 cm 남기지 않고 적법한 수비 자리를 잡았다. A1이 B1과 접촉해 B1을 트라이 라인 너머로 밀어냈다. 레퍼리가 A1에게 페널티 트라이를 주고 볼을 B팀에 준 것은 옳은가?', 1,
  '케이스북 11.93.7의 답: 옳지 않다. B1이 트라이 라인으로 가는 길 전체를 막아 A1에게 득점 기회가 없었다. A1이 적법한 자리의 B1을 불법한 자리로 밀어낸 것이므로 B1에게 코트 이탈 페널티를 주고, 볼은 A팀에 코너에서 준다.', [93, 89], ox=1)
c('11.94.1', 'A1이 프론트코트에서 센터라인 근처까지 와 멈춰 있었다. B4가 다가와 부딪혀 A1의 뒷바퀴가 센터라인에 닿았다. 레퍼리가 A1을 백코트 바이얼레이션으로 몰았다며 B4에게 푸싱 파울을 준 것은 옳은가?', 1,
  '케이스북 11.94.1의 답: 옳지 않다. 처음 접촉이 적법했으므로 파울은 없다. 다만 백코트 바이얼레이션은 선언해야 한다.', [94, 73], ox=1)
c('11.94.2', 'A1이 속공으로 득점을 노리는데 B1이 바로 뒤에서 B2에게 밀려 속도를 냈다. 레퍼리가 B2에게 푸싱 파울을 준 것은 옳은가?', 0,
  '케이스북 11.94.2의 답: 옳다. 동료가 밀어서 도와줄 수는 없다.', [94], ox=0)
c('11.94.3', 'A1이 B1과 B2에게 일부 막힌 상태에서 A4가 뒤에서 A1을 한 번 들이받아(범프) 트라이 라인 너머로 보내 득점했다. 레퍼리가 트라이를 인정한 것은 옳은가?', 0,
  '케이스북 11.94.3의 답: 옳다. 한 번 들이받는 것(범프)은 1차 접촉으로 보아 허용된다.', [94], ox=0)
c('11.94.4', 'A3가 키로 들어가 트라이 라인 근처에서 B2와 부딪힌 뒤, 계속 B2를 밀어 트라이 라인 밖으로 밀어냈다. 레퍼리는 B2에게 코트 이탈 파울을 주어야 하는가?', 1,
  '케이스북 11.94.4의 답: 아니다. 1차 접촉(적법한 충돌) 뒤에 계속 밀어 상대를 불법한 위치로 몰면 미는 쪽에 푸싱 파울을 준다. A3에게 푸싱 파울이다.', [94, 93], ox=1)
c('11.94.5', 'B2와 B3가 트라이 라인 근처에서 A1을 막았지만, 힘이 더 센 A1이 1차 접촉 뒤에도 계속 밀어 B2와 B3를 옆으로 치우고 득점했다. 레퍼리가 트라이를 취소하고 A1에게 푸싱 파울을 준 것은 옳은가?', 1,
  '케이스북 11.94.5의 답: 옳지 않다. 볼을 가진 A1이 상대를 불법한 위치로 몰지 않고 옆으로 치우며 득점했으므로 푸싱 파울이 아니다. 트라이를 인정한다.', [94], ox=1)
c('11.94.6', 'A1이 손으로 미는 행위는 각각 어떻게 판정하는가? 같은 팀 A2를 밀어 수비를 돕는 경우와, 상대 B1의 몸을 미는 경우, 상대 B1의 휠체어를 미는 경우.', 0,
  '케이스북 11.94.6의 답: 동료를 손으로 밀어 수비나 득점을 돕는 것은 푸싱 파울이다. 상대의 몸을 밀거나 상대 휠체어를 미는 것은 일리걸 유스 오브 더 핸즈 파울이다.', [94, 95],
  ch=['동료를 밀면 푸싱 파울, 상대의 몸이나 휠체어를 밀면 일리걸 유스 오브 더 핸즈',
       '셋 다 푸싱 파울', '셋 다 파울 없음'],
  cEn=['Pushing a teammate is a pushing foul; pushing an opponent\'s body or chair is illegal use of the hands',
       'All three are pushing fouls', 'No foul in any case'])
c('11.95.1', 'B2가 A1의 수직 공간으로 손을 뻗어 볼에 닿는 동시에 자기 팔로 A1의 팔을 눌러 A1을 분명히 불리하게 만들었다. 레퍼리는 경기를 계속하게 해야 하는가?', 1,
  '케이스북 11.95.1의 답: 안 된다. 두 접촉이 동시에 일어나 A1이 불리해졌다면 팔 접촉은 파울로 선언해야 한다.', [95], ox=1)
c('11.95.2', 'B4가 A1의 무릎에서 볼을 쳐내려 했고, A1은 두 손으로 볼을 든 채 팔꿈치를 옆으로 들어 B4의 팔에 닿게 했다. 접촉은 수직 공간 밖에서 일어났다. 레퍼리가 B4에게 일리걸 유스 오브 더 핸즈를 준 것은 옳은가?', 1,
  '케이스북 11.95.2의 답: 옳지 않다. 이점도 불이익도 없었으므로 콜하지 않는다.', [95], ox=1)
c('11.95.3', 'A1이 볼을 머리 위로 들고 있었고 B2가 볼을 쳐내려 했다. A1이 B2의 손을 밀어냈다. 레퍼리가 경기를 멈추고 A1에게 일리걸 유스 오브 더 핸즈 파울을 준 것은 옳은가?', 0,
  '케이스북 11.95.3의 답: 옳다. 접촉이 A1의 머리 위에서 끝나는 수직 공간 밖에서 일어났고, 접촉을 시작한 쪽도 A1이다.', [95], ox=0)
c('11.95.4', 'B1이 A1 앞에서 손을 흔들어 패스를 막고 있었고(수직 공간 안), A1이 볼을 이리저리 움직이다 가벼운 접촉이 생겼지만 어느 쪽도 불리해지지 않았다. 레퍼리가 경기를 멈추고 B1에게 파울을 주어야 하는가?', 1,
  '케이스북 11.95.4의 답: 아니다. 이점도 불이익도 없는 우연한 접촉이므로 경기를 계속한다.', [95], ox=1)
c('11.96.1', 'A2가 키에서 패스를 기다리는데 B1이 뒤로 붙어 뒷바퀴를 쳐서 앞 캐스터가 들렸다. 그 결과 A2가 균형을 잃고 넘어지지 않으려고 손을 바닥에 짚었다. 이 경우 무엇을 선언하는가?', 0,
  '케이스북 11.96.1 b)의 답: 버티컬 스피닝 파울이다. A2가 불리해졌고 넘어질 위험으로 위험에 처했다. 같은 케이스 a)처럼 볼을 놓칠 정도로 밀렸을 뿐 위험이 없다면 콜하지 않는다.', [96],
  ch=['버티컬 스피닝 파울', '파울 없음 — 경기 계속'], cEn=['Vertical spinning foul', 'No foul - play on'])
c('11.96.2', 'A2와 B2가 A1을 따라 트라이 라인으로 가던 중, A2가 A1의 길을 터 주려고(블록) B2에게 적법한 충돌을 했다. 그 충돌 때문에 B2가 A1을 회전시켰다. 레퍼리가 B2에게 스피닝 파울을 준 것은 옳은가?', 0,
  '케이스북 11.96.2의 답: 옳다. A1을 회전시킨 것은 B2이므로 B2에게 파울을 준다.', [96], ox=0)
c('11.96.3', 'A1이 코트를 뒤로 물러나며 가고 있었다. B1이 득점을 막으려 A1 뒷바퀴 앞쪽에 범퍼를 대자 A1이 회전하며 휠체어에서 떨어졌다. 스피닝 파울인가?', 1,
  '케이스북 11.96.3의 답: 아니다. A1이 뒤로 가고 있었으므로 휠체어의 뒤쪽이 앞쪽으로 보이고, 접촉은 축보다 앞에서 일어난 것이다.', [96, 84], ox=1)
c('11.97.1', 'A1이 스로인을 하는 중 A2가 1m 반경 안으로 A1 앞을 지나가 반대편에서 볼을 받았다. 레퍼리가 경기를 계속하게 했다. 옳은가?', 1,
  '케이스북 11.97.1의 답: 옳지 않다. 1m 제한선은 중립으로, 스로인 동안 양 팀 모두 침범할 수 없고 침범하면 소유권을 잃는다.', [97, 69], ox=1)
c('11.97.2', 'A1이 트라이 뒤 인바운드에서 A2와 A3에게 가둬진 B1 쪽으로 이동해 세 선수가 모두 1m 안에 있게 되었다. A1이 A3에게 패스하면 어떻게 판정하는가?', 0,
  '케이스북 11.97.2 a)의 답: A3의 1m 파울이다. 같은 케이스 b)에서 A1이 트라이 라인에 아주 가까이 있는 A2의 무릎에 바로 볼을 얹었다면 A2의 1m 파울이다. c)처럼 A1이 3m 떨어진 A4에게 패스한 뒤 B1을 비켜 달라고 요청해도, 선수들은 볼이 인바운더에게 주어지기 전 적법하게 1m 반경 밖에 있었으므로 경기는 그대로 계속되고 B1은 자리를 지킨다. A1은 45도 각도 안으로 코트에 들어와야 하며, 조금 더 큰 각도만 가능하면 플레이 반대쪽으로 B1을 돌아 들어올 수 있다.',
  [97, 69], ch=['A3의 1m 파울', '파울 없음', 'A1의 스로인 바이얼레이션'], cEn=['One-metre foul on A3', 'No foul', 'Throw-in violation on A1'])
c('11.97.3', 'A1이 트라이 뒤에서 스로인하는데 B2가 1m 구역 안으로 들어왔다. 레퍼리가 B2에게 1m 파울을 주고 A팀에 사이드라인 인바운드를 주었다. 옳은 절차인가?', 1,
  '케이스북 11.97.3의 답: 옳지 않다. 스로인 위치는 그대로 엔드라인 어디든 되어야 한다. 트라이 뒤 스로인은 반드시 엔드라인에서 해야 한다.', [97, 69], ox=1)
